fn longest_common_prefix(str1: &Vec<char>, str2: &Vec<char>) -> Vec<char> {
    let mut prefix_len = 0;
    let max_len = std::cmp::min(str1.len(), str2.len());
    
    while prefix_len < max_len && str1[prefix_len] == str2[prefix_len] {
        prefix_len += 1;
    }
    
    // Now prefix_len is the length of the maximal common prefix.
    // Either prefix_len == length of one string (one is prefix of the other),
    // Or at prefix_len, the two characters differ (if both strings have chars there).
    
    str1[0..prefix_len].to_vec()
}